using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class BlockRotationChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify(Action<ConstructionSite,ConstructionBlock> capture=null){
  var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var site=god.GetComponent<CreatureConstructionLearning>().sites[0];var field=typeof(QuestSlice).GetField("state",F);var original=field.GetValue(slice);var geometry=site.Capture();var recipe=site.Recipe;bool paused=site.Paused,locked=site.Locked;var hands=(CarryItem[])typeof(QuestSlice).GetField("held",F).GetValue(slice);Check(hands.All(h=>h==null),"Release carried objects");var people=slice.GetComponentsInChildren<VillagerExploration>();var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();float timeScale=Time.timeScale;Time.timeScale=0;
  bool Turn(bool right,bool left,bool tracked=true,bool blocked=false)=>(bool)typeof(QuestSlice).GetMethod("RotateBlockInput",F).Invoke(slice,new object[]{right,left,tracked,blocked});
  bool Grab(ConstructionBlock b)=>(bool)typeof(QuestSlice).GetMethod("TryGrab",F).Invoke(slice,new object[]{1,b.Item});
  void Release(Ray ray)=>typeof(QuestSlice).GetMethod("Release",F).Invoke(slice,new object[]{1,ray});
  float Yaw(ConstructionBlock b)=>site.PlayerYaw(b.transform.rotation).eulerAngles.y;
  void Click(bool right=true){Turn(false,false);Check(Turn(right,!right),"Fresh rotation press refused");}
  var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};test.Hybrid.time=200;
  try{
   god.Interrupt("Block rotation QA");foreach(var p in people){p.ResetTask();p.GetComponent<VillagerSocial>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerBlockPlay>().ResetTask();}field.SetValue(slice,test);slice.GetComponentInChildren<VillageFamilies>().ResetWorld();slice.SetSanctuaryOpen(false);var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.05f,false);site.Paused=site.Locked=false;site.ResetConstruction();site.Recipe=BuildRecipe.Tower;
   foreach(float z in new[]{-2f,2f}){var column=site.blocks.First(b=>b.Shape==ConstructionShape.Column&&!b.Attached);Check(site.Drop(column,site.World(new Vector3(-12,2.4f,z-12)),site.transform.rotation),"Could not stage north/south support");}
   var beam=site.blocks.First(b=>b.Shape==ConstructionShape.Beam);Check(Grab(beam),"Native beam pickup failed");string before=JsonUtility.ToJson(test);int snaps=site.successfulSnaps;
   Click();Check(Mathf.Abs(Yaw(beam)-90)<.01f&&!Turn(true,false),"Quarter turn repeated while held");Click(false);Check(Mathf.Abs(Yaw(beam))<.01f,"Reverse turn failed");Turn(false,false);Check(!Turn(true,true),"Simultaneous buttons rotated");Turn(false,false);Check(!Turn(true,false,false)&&!Turn(true,false,true),"Tracking return replayed a press");Turn(false,false);Check(!Turn(true,false,true,true)&&!Turn(true,false),"Blocked input replayed a press");Turn(false,false);site.Paused=true;Check(!Turn(true,false),"Paused site rotated");site.Paused=false;Click();Check(Mathf.Abs(Yaw(beam)-90)<.01f&&before==JsonUtility.ToJson(test)&&site.successfulSnaps==snaps&&hands[1]==beam.Item&&beam.Item.held,"Rotation changed ownership, saved state or progress");
   Physics.SyncTransforms();var ray=new Ray(site.World(new Vector3(-12,12,-10.9f)),Vector3.down);Check(site.PlacementPoint(beam,ray,out var target)&&Vector3.Distance(site.Local(target),new Vector3(-12,5.4f,-12))<.01f,"Rotated rim did not resolve north/south span");site.PreviewRay(beam,ray);var preview=(LineRenderer)typeof(ConstructionSite).GetField("preview",F).GetValue(site);Check(preview.enabled,"Rotated preview missing");var points=new Vector3[preview.positionCount];preview.GetPositions(points);var local=points.Select(site.Local).ToArray();Check(Mathf.Abs(local.Max(p=>p.x)-local.Min(p=>p.x)-beam.size.z)<.01f&&Mathf.Abs(local.Max(p=>p.z)-local.Min(p=>p.z)-beam.size.x)<.01f,"Preview footprint did not rotate");capture?.Invoke(site,beam);
   Release(ray);Check(beam.Attached&&hands[1]==null&&Vector3.Distance(beam.Body.position,new Vector3(-12,5.4f,-12))<.01f&&Quaternion.Angle(beam.Body.rotation,Quaternion.Euler(0,90,0))<.01f,"Native drop disagreed with rotated preview");Check(test.placeContributions?.records.Length==1&&test.placeContributions.records[0].actor=="player","Rotation/drop fabricated or duplicated placement credit");
   site.ReturnLoose(beam);var slab=site.blocks.First(b=>b.Shape==ConstructionShape.Slab);Check(Grab(slab),"Slab pickup refused");Click();Physics.SyncTransforms();Release(ray);Check(slab.Attached&&Quaternion.Angle(slab.Body.rotation,Quaternion.Euler(0,90,0))<.01f,"Rotated slab did not span supports");var visitor=people[0];var nav=visitor.GetComponent<IslandNavigator>();Check(site.TryShelterSpot(nav.profile.radius+.08f,nav.profile.height,out _,out var entry),"Rotated roof did not provide geometric cover");visitor.transform.position=entry;nav.ResetRoute();test.Social(0).restNeed=.95f;Check(visitor.TryShelter(site),"Villager refused rotated roof");for(int i=0;i<3000&&test.Social(0).shelterRests==0;i++){test.Hybrid.time+=.05f;visitor.Tick(.05f,false);}Check(test.Social(0).shelterRests==1,"Villager did not use rotated player roof");visitor.ResetTask();
   int index=site.blocks.IndexOf(slab);typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);var loaded=(SliceState)field.GetValue(slice);site.Restore(loaded.construction);Check(loaded.Valid()&&site.blocks[index].Attached&&Quaternion.Angle(site.blocks[index].Body.rotation,Quaternion.Euler(0,90,0))<.01f,"Native reload lost rotated assembly");
   site.ResetConstruction();site.Recipe=BuildRecipe.Arch;foreach(var placement in ConstructionPatterns.Plan(BuildRecipe.Arch)){var piece=site.blocks.First(b=>!b.Attached&&(placement.beam?b.Shape==ConstructionShape.Beam:b.Shape==ConstructionShape.Brick));Check(site.Drop(piece,site.World(placement.position),site.transform.rotation*Quaternion.Euler(0,placement.beam?180:90,0)),"Equivalent recipe piece failed to snap");}Check(site.RecipeComplete,"Equivalent square/end-for-end orientations broke authored recipe");
   Debug.Log("BWVR_BLOCK_ROTATION_PASS: native pickup, press/release edges, reverse/simultaneous/tracking/blocked/pause guards, no rotation rewards, north/south beam preview and native snap, rotated slab and actual villager cover use, player provenance, native Save/Load");
  }finally{Turn(false,false,true,true);if(hands[1]!=null){hands[1].held=false;hands[1].GetComponent<Collider>().enabled=true;hands[1]=null;}foreach(var p in people)p.ResetTask();god.Interrupt("Rotation QA complete");field.SetValue(slice,original);site.Recipe=recipe;site.Restore(geometry);site.Paused=paused;site.Locked=locked;for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}Time.timeScale=timeScale;}
 }
}
}
